const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountDataHub(){
 const host=document.createElement('section');host.className='data-hub';host.innerHTML='<h2>真实数据接入中心</h2><p class="muted">海外市场与宏观背景 · 与国内演示行情分开 · 按需读取，缓存15分钟</p><div class="hub-actions"><button class="primary" data-provider="yfinance">读取海外期货参考</button><button class="quiet" data-provider="fred">读取FRED宏观数据</button></div><div class="hub-output" role="status">点击上方按钮读取真实数据。没有获取成功的数据不会显示为已连接。</div><details><summary>查看文章的12个数据源与接入条件</summary><div class="hub-registry">正在核对接入状态…</div></details>';
 document.querySelector('#workspaceBody').prepend(host);
 const result=host.querySelector('.hub-output');
 host.querySelectorAll('[data-provider]').forEach(b=>b.onclick=async()=>{const id=b.dataset.provider;host.querySelectorAll('[data-provider]').forEach(x=>x.disabled=true);result.textContent='正在请求真实数据，最长约80秒…';try{const r=await fetch('/api/external?provider='+id);if(!r.ok)throw Error();const d=await r.json();if(!host.isConnected)return;
 result.innerHTML=`<p class="${d.status==='ok'?'cyan':'amber'}">${escape({ok:'读取成功',partial:'部分成功',unavailable:'暂不可用',stale:'缓存已过期'}[d.status]||d.status)} · ${escape(d.provider)}${d.fetchedAt?' · 获取 '+escape(new Date(d.fetchedAt).toLocaleString('zh-CN')):''}${d.cached?' · 缓存':''}</p>${d.error?'<p>'+escape(d.error)+'</p>':''}<div class="work-grid">${(d.items||[]).map(i=>`<article class="work-card"><h3>${escape(i.name)}</h3><strong class="data-value">${Number(i.value).toLocaleString('zh-CN',{maximumFractionDigits:4})}</strong> <span>${escape(i.unit)}</span><p>观测日期 ${escape(i.observedAt)}<br>${escape(i.timing)}</p>${spark(i.history)}<a href="${escape(i.source)}" target="_blank" rel="noopener">核对原始来源 ↗</a></article>`).join('')}</div>${d.failures?.length?'<p class="amber">未取得：'+d.failures.map(i=>escape(i.symbol)+'（'+escape(i.reason)+'）').join('、')+'</p>':''}<p class="muted">用途：外围研究；不授予交易许可，不代表国内期货报价。</p>`;
 }catch{result.textContent='数据接口请求失败；没有用演示数据代替。'}finally{host.querySelectorAll('[data-provider]').forEach(x=>x.disabled=false)}});
 try{const r=await fetch('/api/providers');const list=await r.json();if(!host.isConnected)return;host.querySelector('.hub-registry').innerHTML=list.map(p=>`<div class="work-item"><div><b>${escape(p.name)}</b><p>${escape(p.scope)}</p><small>${escape(p.required.length?'所需：'+p.required.join('、'):'无需凭证')}</small></div><a href="${escape(p.docs)}" target="_blank" rel="noopener">${p.adapterImplemented?'已接适配器，读取验证':'待凭证/服务配置'} ↗</a></div>`).join('')}catch{host.querySelector('.hub-registry').textContent='接入状态读取失败'}
}
function spark(rows){if(!rows?.length)return '';const vals=rows.map(r=>r.close),min=Math.min(...vals),span=Math.max(...vals)-min||1;return `<svg viewBox="0 0 280 70" role="img" aria-label="最近观测值趋势"><polyline fill="none" stroke="#71d9ef" stroke-width="1.5" points="${vals.map((v,i)=>`${i*280/Math.max(1,vals.length-1)},${65-(v-min)*60/span}`).join(' ')}"/></svg>`}
